func (r *Registry) prune() {
	finished := 0
	for _, run := range r.runs {
		if run.Finished() {
			finished++
		}
	}
	excess := finished - MaxFinishedRuns
	if excess <= 0 {
		return
	}

	kept := make([]*Run, 0, len(r.runs)-excess)
	for _, run := range r.runs {
		if excess > 0 && run.Finished() {
			excess--
			continue
		}
		kept = append(kept, run)
	}
	r.runs = kept
}

func (r *Registry) now() time.Time {
	if r.clock == nil {
		return time.Now()
	}
	return r.clock()
}
